SELECT shipping_order_id AS shippingOrderId, COUNT(DISTINCT sku_code) AS skuCount FROM wms_shipping_order_item WHERE shipping_order_id IN
#{id}
GROUP BY shipping_order_id

SELECT shipping_order_id AS shippingOrderId, COALESCE(SUM(quantity), 0) AS totalQuantity, COALESCE(SUM(received_quantity), 0) AS receivedQuantity, COALESCE(SUM(quantity - IFNULL(received_quantity, 0) - IFNULL(inbound_reserved_quantity, 0)), 0) AS pendingInboundQuantity FROM wms_shipping_order_item WHERE shipping_order_id IN
#{id}
GROUP BY shipping_order_id

mapper.update:
UPDATE wms_shipping_order_item
SET received_quantity = IFNULL(received_quantity, 0) + #{quantity},
    update_time = NOW()
WHERE id = #{itemId}
  AND (quantity - IFNULL(received_quantity, 0)) >= #{quantity}

UPDATE wms_shipping_order_item
SET inbound_reserved_quantity = IFNULL(inbound_reserved_quantity, 0) + #{quantity},
    update_time = NOW()
WHERE id = #{itemId}
  AND (quantity - IFNULL(received_quantity, 0) - IFNULL(inbound_reserved_quantity, 0)) >= #{quantity}

UPDATE wms_shipping_order_item
SET inbound_reserved_quantity = inbound_reserved_quantity - #{reservedQuantity},
    received_quantity = IFNULL(received_quantity, 0) + #{actualQuantity},
    update_time = NOW()
WHERE id = #{itemId}
  AND inbound_reserved_quantity >= #{reservedQuantity}
  AND (quantity - IFNULL(received_quantity, 0)) >= #{actualQuantity}

