SELECT id FROM wms_purchase_order_item WHERE id IN
#{id}
ORDER BY id FOR UPDATE

SELECT poi.id AS purchaseOrderItemId, poi.sku_code AS skuCode, poi.quantity AS totalQuantity, IFNULL(poi.shipped_quantity, 0) AS shippedQuantity, COALESCE(SUM( CASE WHEN so.id IS NOT NULL AND so.id <> #{shippingOrderId} THEN soi.quantity ELSE 0 END ), 0) AS pendingReservedQuantity FROM wms_purchase_order_item poi LEFT JOIN wms_shipping_order_item soi ON soi.purchase_order_item_id = poi.id LEFT JOIN wms_shipping_order so ON so.id = soi.shipping_order_id AND so.deleted = 0 AND so.shipping_status = 'PENDING' WHERE poi.id IN
#{id}
GROUP BY poi.id, poi.sku_code, poi.quantity, poi.shipped_quantity ORDER BY poi.id FOR UPDATE
